code='''def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    sep_rows = [r for r, row in enumerate(g) if len(set(row)) == 1 and row[0] != 0]
    sep_cols = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != 0]

    def spans(n, separators):
        out, start = [], 0
        for s in separators:
            if start < s:
                out.append((start, s))
            start = s + 1
        if start < n:
            out.append((start, n))
        return out

    row_bands, col_bands = spans(h, sep_rows), spans(w, sep_cols)
    occupied = []
    colors = []
    for r0, r1 in row_bands:
        occ_row, color_row = [], []
        for c0, c1 in col_bands:
            vals = {g[r][c] for r in range(r0, r1) for c in range(c0, c1) if g[r][c] != 0}
            occ_row.append(bool(vals))
            color_row.append(next(iter(vals)) if len(vals) == 1 else None)
        occupied.append(occ_row)
        colors.append(color_row)

    for i in range(len(row_bands) - 1):
        for j in range(len(col_bands) - 1):
            cells = [(i, j), (i, j + 1), (i + 1, j), (i + 1, j + 1)]
            present = [(r, c) for r, c in cells if occupied[r][c]]
            if len(present) != 3:
                continue
            color_set = {colors[r][c] for r, c in present}
            if len(color_set) != 1 or None in color_set:
                continue
            missing_r, missing_c = next((r, c) for r, c in cells if not occupied[r][c])
            donor_c = missing_c + 1 if missing_c == j else missing_c - 1
            r0, r1 = row_bands[missing_r]
            d0, d1 = col_bands[donor_c]
            m0, m1 = col_bands[missing_c]
            if d1 - d0 != m1 - m0:
                continue
            for rr in range(r0, r1):
                for off in range(d1 - d0):
                    value = g[rr][d1 - 1 - off]
                    if value:
                        g[rr][m0 + off] = value
    return g
'''
